{
    using (var img = Image.Load(imagePath))
    {
        // Resize the image to the specified dimensions
        img.Mutate(x => x.Resize(width, height));

        // Choose encoder based on the format
        IImageEncoder encoder;
        if (outputFormat.ToLower() == "jpeg")
        {
            encoder = new JpegEncoder { Quality = quality ?? 90 };
        }
        else if (outputFormat.ToLower() == "png")
        {
            encoder = new PngEncoder { CompressionLevel = compressionLevel ?? 7 };
        }
        else
        {
            throw new ArgumentException("Format must be either 'JPEG' or 'PNG'");
        }

        // Save the image to a memory stream and get the byte array
        using var memoryStream = new MemoryStream();
        img.Save(memoryStream, encoder);
        return memoryStream.ToArray();
    }
