# Function to parse input based on the LL(1) table
# Here we define the parse function that uses the LL(1) table to parse the input
# and handles errors appropriately.
def parse(input_string, ll1_table):
    stack = [('$', 'S')]
    input_tokens = iter(re.findall(r' /* | /* | /* |"[^"]*"| /* |"[^"]*"| /* |"[^"]*"| /* | /* |"[^"]*"| /* |"[^"]*"', input_string))
    current_token = next(input_tokens)

    while stack:
        top = stack[-1]
        if top[0] == current_token:
            if top[0] == '$':
                print('Parsing successful')
                break
            else:
                stack.pop()
                current_token = next(input_tokens, '$')
        elif top[1] in ll1_table and current_token in ll1_table[top[1]]:
            production = ll1_table[top[1]][current_token]
            stack.pop()
            if production != 'ε':
                for symbol in reversed(production.split()):
                    if symbol.isupper():
                        stack.append((symbol, symbol))
        else:
            print(f'Error: Parsing failed. Expected {ll1_table[top[1]].keys()} but found {current_token}')
            break

parse("x = 10", ll1_table)
