        self.position = position
        self.linear_velocity = linear_velocity

class PhysicsUtils:
    @staticmethod
    def velocity_to_position(body, target_position, max_speed, delta_time, step_frequency):
        # Define a small threshold to consider the body at the target position
        epsilon = 0.001

        # Get the current position of the body
        position = body.position

        # Calculate the direction vector from current position to target position
        target_direction = target_position - position

        # Calculate the distance to the target
        distance_to_target = target_direction.length()

        # Check if the body is already at the target position within a small threshold
        if distance_to_target <= epsilon:
            return Vector2(0, 0)  # Return zero velocity if the body is at the target

        # Calculate the maximum distance the body can travel in this frame
        max_distance_this_frame = max_speed * delta_time

        # Calculate the desired velocity to reach the target position directly
        desired_velocity = target_direction.normalized() * max_speed

        # Clamp the desired velocity if the distance to the target is less than the max distance this frame
        if distance_to_target < max_distance_this_frame:
            desired_velocity *= distance_to_target / max_distance_this_frame

        # Determine the lerp factor based on the distance to the target
        # The closer the body is to the target, the slower the adjustment
        lerp_factor = min(1.0, distance_to_target / (max_distance_this_frame * 2))  # Adjust the divisor as necessary

        # Smoothly adjust the current velocity towards the desired velocity
        current_velocity = body.linear_velocity
        smoothed_velocity = current_velocity.lerp(desired_velocity, lerp_factor)

        return smoothed_velocity

