Here is how you can achieve this:

```python
from typing import List, Union

class Result:
    def __init__(self, value=None, error=None):
        self.value = value
        self.error = error

    def is_ok(self):
        return self.error is None

    @staticmethod
    def ok(value):
        return Result(value=value)

    @staticmethod
    def err(error):
        return Result(error=error)

    def map(self, func):
        if self.is_ok():
            return func(self.value)
        else:
            return self

    def and_then(self, func):
        if self.is_ok():
            result = func(self.value)
            if result and not result.is_ok():
                return result
            else:
                return self.ok(result)
        else:
            return self

    @staticmethod
    def collect(results: List['Result']):
        if not all(r.is_ok() for r in results):
            errors = [r.error for r in results if not r.is_ok()]
            return Result.err('\n'.join(errors))
        else:
            return Result.ok([r.value for r in results])


def get_sym_json_path(args, region_json) -> Result:
