% Load the image
originalImage = imread('saturn.tif');

% Function to perform degradation
function degradedImage = degradeImage(image, nn)
    % Compute the Fourier transform
    x = fft2(image);
    % Adding noise to specific frequency components
    x(10,10) = x(10,10) + nn; 
    x(10,11) = x(10,11) + nn;
    x(11,10) = x(11,10) + nn;
    x(11,11) = x(11,11) + nn;
    % Transform back to spatial domain
    degradedImage = real(ifft2(x));
end

% Function to restore image using Total Variation (TV) regularization
function restoredImage = restoreImageTV(degradedImage, weight)
    % Convert to grayscale if necessary
    if size(degradedImage, 3) > 1
        degradedImage = rgb2gray(degradedImage);
    end

    % Apply Total Variation denoising
    restoredImage = tvdenoise(degradedImage, weight);
end

% Function to restore image using Wavelet Denoising
function restoredImage = restoreImageWavelet(degradedImage, threshold)
    % Convert to grayscale if necessary
    if size(degradedImage, 3) > 1
        degradedImage = rgb2gray(degradedImage);
    end

    % Apply Wavelet denoising
    restoredImage = wdenoise2(degradedImage, 'ThresholdRule', 'SURE', 'Threshold', threshold);
end

% Degradation
degradedImage = degradeImage(originalImage, 1 * 1e+6);

% Restoration using TV regularization
restoredImageTV = restoreImageTV(degradedImage, 0.1);

% Restoration using Wavelet Denoising
restoredImageWavelet = restoreImageWavelet(degradedImage, 2);

% Display images
