ssimTV = ssim(originalImage, uint8(restoredImageTV));

psnrWavelet = psnr(originalImage, uint8(restoredImageWavelet));
ssimWavelet = ssim(originalImage, uint8(restoredImageWavelet));

fprintf('TV Restoration:\nPSNR: %.2f dB\nSSIM: %.4f\n', psnrTV, ssimTV);
